/**
 * Robust date parser for Duty Register dates
 * Handles formats like:
 * - "9/21/26", "10/13/26", "12/29/26" (M/D/YY with 2-digit year conversion)
 * - "07th Oct to 11th Oct 2026", "15th March to 23rd March 2027" (date ranges)
 * - Standard ISO or locale date strings
 */
export function parseDutyDate(val: any): number | null {
  if (!val || typeof val !== 'string') return null;
  val = val.trim();
  if (!val) return null;

  // 1. M/D/YY or M/D/YYYY
  const mdyMatch = val.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})$/);
  if (mdyMatch) {
    let month = parseInt(mdyMatch[1], 10);
    let day = parseInt(mdyMatch[2], 10);
    let year = parseInt(mdyMatch[3], 10);
    if (year < 100) year += 2000;
    if (month > 12 && day <= 12) {
      const temp = month;
      month = day;
      day = temp;
    }
    return new Date(year, month - 1, day).getTime();
  }

  // 2. Date ranges like "07th Oct to 11th Oct 2026" or "15th March to 23rd March 2027"
  const rangeMatch = val.match(/(\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]+)(?:.*?(\d{4}))?/i);
  if (rangeMatch) {
    const day = parseInt(rangeMatch[1], 10);
    const monthStr = rangeMatch[2];
    const year = rangeMatch[3] ? parseInt(rangeMatch[3], 10) : (val.match(/\d{4}/) ? parseInt(val.match(/\d{4}/)[0], 10) : 2026);
    const parsed = new Date(`${monthStr} ${day}, ${year}`);
    if (!isNaN(parsed.getTime())) return parsed.getTime();
  }

  // 3. Fallback to standard Date.parse
  const parsed = Date.parse(val);
  if (!isNaN(parsed)) return parsed;

  return null;
}

